// playwright-cli run-code --filename Tools/TemporalEvidence/check-viewer.js
// Run against the synthetic fixture generated by test_viewer.fixture, not real evidence.
async page => {
  await page.waitForFunction(() => document.querySelector('#frame').naturalWidth === 2);
  await page.locator('#mark-start').click();
  await page.locator('#play').click();
  await page.waitForFunction(() => document.querySelector('#position').textContent.startsWith('Frame 2 / 2'));
  await page.waitForFunction(() => document.querySelector('#play').textContent === 'Play segment');
  if (await page.locator('#segment').inputValue() !== 'segment-a') throw Error('Playback crossed segment');
  if (!(await page.locator('#gap').textContent()).includes('retained_gap')) throw Error('Missing gap');
  await page.locator('#mark-end').click();
  await page.locator('#reviewer').fill('Synthetic browser test');
  await page.locator('#note').fill('Fixture only. No physical handling observation.');
  const draft = await page.evaluate(async () => {
    let blob; const original = URL.createObjectURL;
    URL.createObjectURL = value => { blob = value; return original(value); };
    document.querySelector('#download').click(); URL.createObjectURL = original;
    return JSON.parse(await blob.text());
  });
  if (draft.sourceIndexSHA256 !== 'a'.repeat(64) || draft.observations[0].startFrameID !== 'f0'
      || draft.observations[0].endFrameID !== 'f1' || draft.status !== 'indeterminate') throw Error('Invalid review draft');
  await page.locator('#native').check();
  if (!await page.locator('#viewport.native').count()) throw Error('Native presentation control failed');
  await page.locator('#segment').selectOption('segment-b');
  await page.waitForFunction(() => document.querySelector('#position').textContent.startsWith('Frame 1 / 1'));
  if (!await page.locator('#download').isDisabled()) throw Error('Cross-segment marks retained');
  if (await page.locator('#error').textContent()) throw Error('Viewer reports an error');
  return {status: 'passed', scope: 'synthetic viewer controls, timing, segment boundary and review binding'};
}
